template <typename InputIt, typename OutputIt>
OutputIt unique_copy_logic(InputIt first, InputIt last, OutputIt result) {
    if (first == last) return result;

    // Track the value of the last copied element
    auto last_copied_val = *first;
    *result = last_copied_val;
    result++;
    first++;

    while (first != last) {
        if (!(*first == last_copied_val)) {
            last_copied_val = *first;
            *result = last_copied_val;
            result++;
        }
        first++;
    }
    return result;
}
